import csv

# Read patient sex data
patient_sex = {}
with open('patient_sex.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        patient_sex[row['ID']] = row['SEX']

# Read laboratory data and find specific records
results = []
with open('csv/Laboratory.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        pid = row['ID']
        if pid not in patient_sex or patient_sex[pid] != 'M':
            continue

        wbc = row.get('WBC', '').strip()
        fg = row.get('FG', '').strip()
        date = row.get('Date', '')

        if not wbc:
            continue

        try:
            wbc_val = float(wbc)
        except:
            continue

        # Check if WBC is normal (4.0-10.0)
        if 4.0 <= wbc_val <= 10.0:
            if fg:
                try:
                    fg_val = float(fg)
                    # FG normal range is 2.0-4.0 g/L
                    if fg_val < 2.0 or fg_val > 4.0:
                        results.append((pid, date, wbc_val, fg_val))
                except:
                    pass

print(f'Total: {len(results)}')
for r in results:
    print(r)

